$('sd').addEventListener('click',function(e){var b=e.target.closest&&e.target.closest('#boot button');if(!b)return;S.boot=b.getAttribute('data-v');[].forEach.call($('boot').children,function(x){x.classList.toggle('on',x===b);});});
