function vSupply(){var v=parseFloat(val('sv'));return bad('sv',!(v>=4.9&&v<=5.1&&/^\d+(\.\d+)?$/.test(val('sv'))));}
var CAPAT=function(hh){return{l:14,t:visH()-hh-14};};
